        { slug="depths-of-the-damned/chink-in-their-armour", id="dp_chink_in_their_armour", en="Chink in their Armour", cn="渗透盔甲", desc="+15% Rending when at, or over, 10 stacks of Focus.", desc_cn="拥有10层或更多“专注”时，获得+15%撕裂。", cat="keymod", x=416, y=1654 },
        { slug="depths-of-the-damned/tunnel-vision", id="dp_tunnel_vision", en="Tunnel Vision", cn="视野狭窄", desc="+4% Toughness Replenishment for each stack of Focus. In addition, weakspot kills restore 10% Stamina.", desc_cn="每层“专注”提供+4%韧性恢复量。此外，弱点击杀恢复10%耐力。", cat="keymod", x=394, y=1721 },
        { slug="depths-of-the-damned/long-range-assassin", id="dp_long_range_assassin", en="Long Range Assassin", cn="远程刺客", desc="Increase Maximum stacks of Focus from 10 to 15 .", desc_cn="", cat="keymod", x=416, y=1789 },
        { slug="depths-of-the-damned/weapons-specialist", id="dp_weapons_specialist", en="Weapons Specialist", cn="武器专家", desc="Gain Ranged Specialist on Melee Kills (Stacks 10 times). Gain Melee Specialist on Ranged Kill (Stacks 1 times.) When you wield your Ranged Weapon, you activate your Ranged Specialist effect to gain +2% Ranged Attack Speed, 2% Reload Speed, as well as +33% Ranged Critical Hit Chance on your next shot, per stack. Lasts 10 s. When you wield your Melee Weapon, you activate your Melee Specialist effect, to gain +15% Melee Attack Speed, and 10% Dodge Speed and Dodge Distance. Lasts 10 s.", desc_cn="近战击杀获得“远程专家”（最多10层）；远程击杀获得“近战专家”（最多1层）。装备远程武器时激活“远程专家”：每层提供+2%远程攻击速度、+2%装填速度，并使下一发射击获得+33%远程暴击率，持续10秒。装备近战武器时激活“近战专家”：获得+15%近战攻击速度，闪避速度和闪避距离均+10%，持续10秒。", cat="keystone", x=1046, y=1721 },
        { slug="depths-of-the-damned/on-your-toes", id="dp_on_your_toes", en="On Your Toes", cn="时刻警觉", desc="Activating Melee Specialist and Ranged Specialist replenishes 20% Toughness. 3 s Cooldown for each.", desc_cn="激活近战专家或远程专家时恢复：\n• 20% 韧性。\n• 每种效果冷却 3 秒。", cat="keymod", x=1159, y=1721 },
        { slug="depths-of-the-damned/always-prepared", id="dp_always_prepared", en="Always Prepared", cn="有备无患", desc="Activating Ranged Specialist replenishes up to 3.3% of your missing ammo in your Clip from your Reserve, rounded up, for each stack.", desc_cn="", cat="keymod", x=1136, y=1789 },
        { slug="depths-of-the-damned/invigorated", id="dp_invigorated", en="Invigorated", cn="活力焕发", desc="Activating Melee Specialist restores 20% Stamina and grants 25% Stamina Cost Reduction for 3 s.", desc_cn="激活“近战专家”时恢复20%耐力，并使耐力消耗降低25%，持续3秒。", cat="keymod", x=1136, y=1654 },
        { slug="depths-of-the-damned/focus-target", id="dp_focus_target", en="Focus Target!", cn="锁定目标", desc="Gain Focus Target every 1.5 s (Stacks 4 times). Tagging an Enemy applies the Focus Target stacks to them, causing them to take +5% additional Damage for each stack, and resets your Focus Target stacks to 1.", desc_cn="每1.5秒获得一层“锁定目标”，最多4层。标记敌人时会将当前层数施加到该敌人身上，使其每层额外受到5%伤害，并将你的“锁定目标”层数重置为1层。", cat="keystone", x=776, y=1721 },
        { slug="depths-of-the-damned/target-down", id="dp_target_down", en="Target Down!", cn="目标击倒！", desc="If an Enemy you have Tagged dies, replenish 5% Toughness and 5% Stamina for each stack of Focus Target applied, to you and Allies in Coherency.", desc_cn="", cat="keymod", x=709, y=1811 },
        { slug="depths-of-the-damned/redirect-fire", id="dp_redirect_fire", en="Redirect Fire!", cn="转移火力！", desc="If an Enemy you have Tagged dies, grant +2.5% Damage for each stack of Focus Target applied, to you and Allies in Coherency. Lasts 10 s.", desc_cn="", cat="keymod", x=844, y=1811 },
        { slug="depths-of-the-damned/focussed-fire", id="dp_focussed_fire", en="Focused Fire", cn="集中火力", desc="Focus Target Max Stacks increased to 6 .", desc_cn="", cat="keymod", x=776, y=1856 },
        { slug="depths-of-the-damned/one-motion", id="dp_one_motion", en="One Motion", cn="行云流水", desc="+50% Weapon Swap Speed.", desc_cn="武器切换速度+50%。", cat="passive", x=866, y=461 },
        { slug="depths-of-the-damned/lock-and-load", id="dp_lock_and_load", en="Lock and Load", cn="荷枪实弹", desc="+25% Clip Size, rounded up.", desc_cn="弹匣容量+25%，结果向上取整。", cat="passive", x=506, y=1631 },
        { slug="depths-of-the-damned/covert-operative", id="dp_covert_operative", en="Covert Operative", cn="秘密特工", desc="+30% Damage to Ranged Backstab Attacks.", desc_cn="• +30% 远程背刺攻击伤害。", cat="passive", x=844, y=979 },
        { slug="depths-of-the-damned/withering-fire-2", id="dp_withering_fire_2", en="Withering Fire", cn="凋零烈焰", desc="+50% Ranged Cleave.", desc_cn="+50%远程顺劈。", cat="passive", x=596, y=979 },
        { slug="depths-of-the-damned/melee-damage-boost-cffd3f48", id="dp_melee_damage_boost_cffd3f48", en="Melee Damage Boost", cn="近战增幅", desc="+15% Melee Damage.", desc_cn="近战伤害+15%。", cat="stat", x=866, y=1249 },
