        { slug="depths-of-the-damned/disdain", id="dp_disdain", en="Disdain", cn="蔑视", desc="+5% Damage on your next Melee Attack for each Enemy Hit. Stacks 5 times.", desc_cn="", cat="passive", x=844, y=349 },
