        { slug="depths-of-the-damned/blades-of-faith", id="dp_blades_of_faith", en="Blades of Faith", cn="信仰之刃", desc="Throw a consecrated knife to deal high Damage to a Single Enemy. Very effective against most Enemies; less effective versus Carapace Armour. - Quick Throw - Killing Elite & Special Enemies in Melee replenishes 1 knife - Ammo boxes replenish knives", desc_cn="", cat="blitz", x=1024, y=709 },
        { slug="depths-of-the-damned/enduring-faith", id="dp_enduring_faith", en="Enduring Faith", cn="坚韧信仰", desc="+40% Toughness Damage Reduction on Critical Hit for 4 s.", desc_cn="暴击后获得+40%韧性伤害减免，持续4秒。", cat="passive", x=664, y=1586 },
        { slug="depths-of-the-damned/second-wind", id="dp_second_wind", en="Second Wind", cn="精力复苏", desc="Replenish 15% Toughness on a Successful Dodge.", desc_cn="• 15% 韧性 成功闪避时恢复。", cat="passive", x=911, y=439 },
        { slug="depths-of-the-damned/restoring-faith", id="dp_restoring_faith", en="Restoring Faith", cn="恢复信仰", desc="On taking Damage, heal 20% of that Damage. Occurs over 4 s.", desc_cn="受到生命 伤害 时，4 秒内治愈 20% 该伤害。", cat="passive", x=754, y=1586 },
        { slug="depths-of-the-damned/bleed-for-the-emperor", id="dp_bleed_for_the_emperor", en="Bleed for the Emperor", cn="为了帝皇", desc="Damage that would take your Health to the next Wound is reduced by 40% .", desc_cn="• - 40% 将你生命 减至下一个伤痕 的伤害。", cat="passive", x=934, y=1699 },
        { slug="depths-of-the-damned/vicious-offering", id="dp_vicious_offering", en="Vicious Offering", cn="恶毒赠礼", desc="Replenish 10% Toughness on Heavy Attack Kill.", desc_cn="• 10% 韧性 重攻击杀时恢复。", cat="passive", x=1024, y=439 },
        { slug="depths-of-the-damned/dance-of-death", id="dp_dance_of_death", en="Dance of Death", cn="死亡之舞", desc="-75% Spread and -50% Recoil for 3 s on successful Dodge.", desc_cn="成功闪避后 3 秒内获得：\n• -75% 散布 和\n• -50% 后坐力。", cat="passive", x=911, y=1114 },
        { slug="depths-of-the-damned/benediction", id="dp_benediction", en="Benediction", cn="恩赐", desc="+15% Toughness Damage Reduction for you and Allies in Coherency. This is an augmented version of the base Aura, The Emperor's Will .", desc_cn="• +15% 韧性伤害减免 对你和协同范围内的盟友。\n• 为基础光环 The Emperor's Will 的增强版本。\n\n• 不会与其他狂信徒的相同光环叠加。", cat="aura", x=641, y=1204 },
        { slug="depths-of-the-damned/duellist", id="dp_duellist", en="Duellist", cn="决斗者", desc="+50% Finesse Damage for 3 s on successful Dodge.", desc_cn="• 成功闪避后 3 秒内，+50% 灵巧伤害。", cat="passive", x=956, y=529 },
        { slug="depths-of-the-damned/beacon-of-purity", id="dp_beacon_of_purity", en="Beacon of Purity", cn="纯洁信标", desc="Heal 1.5 Corruption from the current Wound for you and Allies in Coherency every 1 s.", desc_cn="每1秒为你和协同范围内的盟友治疗当前伤口中的1.5点腐化。", cat="aura", x=844, y=1204 },
        { slug="depths-of-the-damned/chorus-of-spiritual-fortitude", id="dp_chorus_of_spiritual_fortitude", en="Chorus of Spiritual Fortitude", cn="不屈灵魂合唱", desc="Wield a holy relic that releases 5 energy pulses every 0.8 s. While channeling, Allies in Coherency are Stun Immune and Unkillable. Each pulse Replenishes 45% Toughness and also grants +15 Max Toughness, up to +75 total. After the first pulse, only Enemies within 8 m are Staggered or Suppressed by later pulses. Base Cooldown: 60 s.", desc_cn="挥舞圣物，每0.8秒释放一次能量脉冲，共5次。引导期间，协同范围内的盟友免疫眩晕且不会死亡。每次脉冲恢复45%韧性，并额外提供+15最大韧性，最多累计+75。第一次脉冲后，后续脉冲只会使8米内的敌人踉跄或受到压制。基础冷却时间60秒。", cat="ability", x=844, y=1406 },
        { slug="depths-of-the-damned/shield-of-contempt", id="dp_shield_of_contempt", en="Shield of Contempt", cn="轻蔑之盾", desc="When you or an Ally in Coherency takes damage, they gain +60% Damage Reduction for 4 s. Triggers every 8 s.", desc_cn="你或协同范围内的盟友受到生命 伤害 时，4 秒内获得：\n• +60% 伤害抗性。\n\n• 每 8 秒触发一次。", cat="passive", x=844, y=911 },
        { slug="depths-of-the-damned/fury-of-the-faithful", id="dp_fury_of_the_faithful", en="Fury of the Faithful", cn="有信者之怒", desc="Dash forward, Replenishing 50% Toughness & gaining +20% Attack Speed for 10 s. Your next Melee Hit gains +25% Damage, has +100% Rending, and is a guaranteed Critical Hit. Base Cooldown: 30 s This is an augmented version of Chastise the Wicked .", desc_cn="向前突进，恢复50%韧性，并获得+20%攻击速度，持续10秒。你的下一次近战命中获得+25%伤害和+100%撕裂，并必定暴击。基础冷却时间30秒。这是“惩戒邪恶”的强化版本。", cat="ability", x=574, y=1406 },
        { slug="depths-of-the-damned/until-death", id="dp_until_death", en="Until Death", cn="死战到底", desc="Fatal Damage instead makes you Unkillable for 8 s. Occurs every 120 s.", desc_cn="受到致命伤害时改为进入8秒不会死亡状态。每120秒最多触发一次。", cat="keystone", x=844, y=799 },
        { slug="depths-of-the-damned/holy-cause", id="dp_holy_cause", en="Holy Cause", cn="神圣事业", desc="Each pulse grants +8% Toughness Damage Reduction to you and Allies in Coherency, stacking up to 5 times. Lasts 10 s.", desc_cn="每次脉冲为你和协同范围内的盟友提供+8%韧性伤害减免，最多叠加5层，持续10秒。", cat="abilmod", x=731, y=1406 },
        { slug="depths-of-the-damned/ecclesiarchs-call", id="dp_ecclesiarchs_call", en="Ecclesiarch's Call", cn="教宗之唤", desc="Each pulse grants +6% Damage to you and Allies in Coherency, stacking up to 5 times. Lasts 10 s.", desc_cn="每次脉冲为你和协同范围内的盟友提供+6%伤害，最多叠加5层，持续10秒。", cat="abilmod", x=956, y=1406 },
        { slug="depths-of-the-damned/desperation", id="dp_desperation", en="Desperation", cn="背水一战", desc="Up to +20% Melee Damage based on missing Stamina.", desc_cn="", cat="passive", x=754, y=1699 },
        { slug="depths-of-the-damned/redoubled-zeal", id="dp_redoubled_zeal", en="Redoubled Zeal", cn="倍增狂热", desc="Fury of the Faithful now has 2 charges.", desc_cn="• 有信者之怒 现在有 2 个充能。", cat="abilmod", x=484, y=1474 },
        { slug="depths-of-the-damned/shroudfield", id="dp_shroudfield", en="Shroudfield", cn="隐秘领域", desc="Enter Stealth for 3 s. While in Stealth gain +20% Movement Speed, +150% Backstab Damage, +150% Finesse Damage, +100% Critical Chance & +100% Melee Rending. Attacking makes you leave Stealth. Base Cooldown: 30 s", desc_cn="进入隐身状态3秒。隐身期间获得+20%移动速度、+150%背刺伤害、+150%精巧伤害、+100%暴击率和+100%近战撕裂。发动攻击会结束隐身。基础冷却时间30秒。", cat="ability", x=1114, y=1406 },
        { slug="depths-of-the-damned/thy-wrath-be-swift", id="dp_thy_wrath_be_swift", en="Thy Wrath be Swift", cn="勃然大怒", desc="Enemy Melee Attacks cannot Stun you. On taking Damage, gain +15% Movement Speed for 2 s.", desc_cn="• 受到伤害 后 2 秒内，+15% 移动速度。\n• 敌人近战攻击无法眩晕 你。", cat="passive", x=1046, y=911 },
        { slug="depths-of-the-damned/master-crafted-shroudfield", id="dp_master_crafted_shroudfield", en="Master-Crafted Shroudfield", cn="大师级隐秘领域", desc="Shroudfield duration increased by 2 s. Upon leaving Stealth, gain -75% Threat and 50% Backstab Damage for 5 s.", desc_cn="• 隐秘领域 持续时间延长 2 秒。\n\n离开隐身 后 5 秒内获得：\n• + 50% 背刺伤害 和\n• -75% 威胁。", cat="abilmod", x=1249, y=1406 },
        { slug="depths-of-the-damned/good-balance", id="dp_good_balance", en="Good Balance", cn="四平八稳", desc="A successful Dodge grants +25% Damage Reduction for 2.5 s.", desc_cn="• 成功闪避后 2.5 秒内，+25% 伤害减免。", cat="passive", x=1046, y=1046 },
        { slug="depths-of-the-damned/enemies-within-enemies-without", id="dp_enemies_within_enemies_without", en="Enemies Within, Enemies Without", cn="内忧外患", desc="Replenish +2.5% Toughness per Second while within 5 m Range of an Enemy, increased by +1% per Enemy. Monstrosities count as 5 . Max +7.5% .", desc_cn="", cat="passive", x=776, y=439 },
        { slug="depths-of-the-damned/invigorating-revelation", id="dp_invigorating_revelation", en="Invigorating Revelation", cn="振奋启示", desc="Shroudfield Replenishes 50% Toughness. Gain +30% Damage Resistance for 8 s upon exiting Stealth.", desc_cn="“隐秘领域”恢复50%韧性。离开隐身时获得+30%伤害抗性，持续8秒。", cat="abilmod", x=1204, y=1496 },
        { slug="depths-of-the-damned/faithful-frenzy", id="dp_faithful_frenzy", en="Faithful Frenzy", cn="信仰狂乱", desc="+10% Melee Attack Speed and +5% Movement Speed.", desc_cn="近战攻击速度+10%，移动速度+5%。", cat="passive", x=844, y=1294 },
        { slug="depths-of-the-damned/martyrs-purpose", id="dp_martyrs_purpose", en="Martyr's Purpose", cn="殉道者之愿", desc="Up to +50% Ability Cooldown Regeneration based on Missing Health. Max reached at 25% Current Health.", desc_cn="依缺失生命 最多 +50% 技能冷却 恢复速度。当前生命 为 25% 时达到最大值。", cat="abilmod", x=844, y=1586 },
        { slug="depths-of-the-damned/faiths-fortitude", id="dp_faiths_fortitude", en="Faith's Fortitude", cn="信仰之勇", desc="+2 Wounds.", desc_cn="+2 伤痕。", cat="passive", x=934, y=1586 },
        { slug="depths-of-the-damned/martyrdom", id="dp_martyrdom", en="Martyrdom", cn="殉道", desc="+10% Melee Damage for each missing Wound, up to a maximum of 5 missing Wounds.", desc_cn="• 每个缺失的伤痕 +10% 近战伤害，最多 5 个缺失伤痕。", cat="keystone", x=844, y=1699 },
        { slug="depths-of-the-damned/i-shall-not-fall", id="dp_i_shall_not_fall", en="I Shall Not Fall", cn="不灭意志", desc="Martyrdom grants +7.5% Toughness Damage Reduction per stack.", desc_cn="• 每层 殉道 +7.5% 韧性伤害减免。", cat="keymod", x=776, y=1789 },
        { slug="depths-of-the-damned/maniac", id="dp_maniac", en="Maniac", cn="狂热者", desc="Martyrdom grants +6% Attack Speed per stack.", desc_cn="• 每层 殉道 +6% 攻击速度。", cat="keymod", x=911, y=1789 },
        { slug="depths-of-the-damned/sustained-assault", id="dp_sustained_assault", en="Sustained Assault", cn="持续突击", desc="+4% Melee Damage for 5 s on Hitting an Enemy with a Melee Attack. Stacks 5 times.", desc_cn="• 近战攻击命中敌人后 5 秒内，+4% 近战伤害。\n• 最多 5 层。", cat="passive", x=641, y=911 },
        { slug="depths-of-the-damned/pious-cut-throat", id="dp_pious_cut_throat", en="Pious Cut-Throat", cn="虔诚刺客", desc="+75% Ability Cooldown Regeneration for 2 s after a Melee Backstab or Melee Weakspot hit.", desc_cn="• 近战背刺或弱点命中后 2 秒内，+75% 技能冷却 恢复速度。", cat="abilmod", x=1114, y=1586 },
        { slug="depths-of-the-damned/inexorable-judgement", id="dp_inexorable_judgement", en="Inexorable Judgement", cn="命定审判", desc="Moving grants you Momentum (Stacks 20 times). When you Hit an Enemy, spend all Momentum, gaining +1% Melee Attack Speed, +1% Ranged Attack Speed, and +1% Damage per Stack. Lasts 6 s.", desc_cn="移动会获得“动量”，最多叠加20层。命中敌人时消耗全部动量，每层提供+1%近战攻击速度、+1%远程攻击速度和+1%伤害，持续6秒。", cat="keystone", x=1114, y=1699 },
        { slug="depths-of-the-damned/inebriates-poise", id="dp_inebriates_poise", en="Inebriate's Poise", cn="飘忽身形", desc="Gain 3 Stacks of Momentum on a successful Dodge.", desc_cn="• + 3 层势能，成功闪避时触发。", cat="keymod", x=1181, y=1789 },
        { slug="depths-of-the-damned/invocation-of-death", id="dp_invocation_of_death", en="Invocation of Death", cn="死亡祷文", desc="+100% Ability Cooldown Regeneration for 3 s on Melee Critical Hits.", desc_cn="• 近战暴击命中 时，+100% 技能冷却 恢复速度，持续 3 秒。", cat="abilmod", x=574, y=1586 },
        { slug="depths-of-the-damned/the-masters-retribution", id="dp_the_masters_retribution", en="The Master's Retribution", cn="大师的反击", desc="Knock back the Attacker on taking a Melee Hit. 8 s Cooldown.", desc_cn="受到近战攻击时打飞攻击者。\n• 冷却：8 秒。", cat="passive", x=776, y=979 },
        { slug="depths-of-the-damned/blazing-piety", id="dp_blazing_piety", en="Blazing Piety", cn="炽热虔诚", desc="+15% Critical Hit Chance for 8 s when in Fury. Fury is triggered when 25 Enemies have died within 25 m. Critical Hits also count up towards triggering Fury.", desc_cn="25 米内有 25 名敌人死亡时，进入狂怒 并获得 8 秒：\n• +15% 暴击率。\n\n暴击 命中也计入触发狂怒 的次数。", cat="keystone", x=574, y=1699 },
        { slug="depths-of-the-damned/stalwart", id="dp_stalwart", en="Stalwart", cn="死忠", desc="Triggering Fury Replenishes 50% Toughness. In addition, while Fury is Active, you have +25% Toughness Damage Reduction and replenish 2% Toughness each second.", desc_cn="触发狂怒 恢复：\n• 50% 韧性。\n\n狂怒 启用期间获得：\n• +25% 韧性伤害减免，\n• 2% 韧性 /秒。", cat="keymod", x=574, y=1834 },
        { slug="depths-of-the-damned/righteous-warrior", id="dp_righteous_warrior", en="Righteous Warrior", cn="正义勇士", desc="+10% Critical Hit Chance from Blazing Piety .", desc_cn="• 炽热虔诚 额外增加 +10% 暴击率。", cat="keymod", x=641, y=1789 },
        { slug="depths-of-the-damned/infectious-zeal", id="dp_infectious_zeal", en="Infectious Zeal", cn="迅疾狂热", desc="Allies in Coherency have +10% Critical Hit Chance while Blazing Piety is active.", desc_cn="炽热虔诚 启用期间，协同范围内的盟友获得：\n• +10% 暴击率。", cat="keymod", x=506, y=1789 },
        { slug="depths-of-the-damned/stunstorm-grenade", id="dp_stunstorm_grenade", en="Stunstorm Grenade", cn="眩晕风暴手雷", desc="Throw a grenade that stuns all Enemies within its blast radius. This is an augmented version of Stun Grenade with +50% blast radius.", desc_cn="", cat="blitz", x=664, y=709 },
        { slug="depths-of-the-damned/melee-damage-boost-0e0cbc5b", id="dp_melee_damage_boost_0e0cbc5b", en="Melee Damage Boost", cn="近战增幅", desc="+10% Melee Damage.", desc_cn="近战伤害+10%。", cat="stat", x=574, y=1496 },
        { slug="depths-of-the-damned/toughness-damage-reduction-f19a0ccc", id="dp_toughness_damage_reduction_f19a0ccc", en="Toughness Damage Reduction", cn="韧性减伤", desc="+10% Toughness Damage Reduction.", desc_cn="韧性伤害减免+10%。", cat="stat", x=844, y=1496 },
        { slug="depths-of-the-damned/melee-damage-boost-cae861f3", id="dp_melee_damage_boost_cae861f3", en="Melee Damage Boost", cn="近战增幅", desc="+10% Melee Damage.", desc_cn="近战伤害+10%。", cat="stat", x=1114, y=1496 },
        { slug="depths-of-the-damned/retributors-stance-2", id="dp_retributors_stance_2", en="Retributor's Stance", cn="惩戒者姿态", desc="During its Duration, replenish 0.5% Toughness per second per spent Stack of Momentum, up to 10%.", desc_cn="效果持续期间，每消耗一层“势能”每秒恢复0.5%韧性，最高10%。", cat="keymod", x=1046, y=1789 },
        { slug="depths-of-the-damned/unrelenting-fury", id="dp_unrelenting_fury", en="Unrelenting Fury", cn="无尽狂怒", desc="Killing an Elite or Specialist within 5 s of using Fury of the Faithful restores +20% Ability Cooldown. Maximum once per use.", desc_cn="使用 有信者之怒 后 5 秒内击杀精英或专家，恢复：\n• +20% 技能冷却。\n\n• 每次使用最多触发一次。", cat="abilmod", x=461, y=1406 },
        { slug="depths-of-the-damned/zealous", id="dp_zealous", en="Zealous", cn="热忱", desc="-15% Stamina Cost and 0.15 s Stamina Regeneration Delay Reduction, for you and Allies in Coherency.", desc_cn="", cat="aura", x=1046, y=1204 },
        { slug="depths-of-the-damned/unfaltering", id="dp_unfaltering", en="Unfaltering", cn="不屈之志", desc="Become Uninterruptible while charging Melee Attacks. Remove +100% of Heavy Melee Attack Movement Speed penalties.", desc_cn="蓄力近战攻击时不会被打断，并移除100%的重型近战攻击蓄力移动速度惩罚。", cat="passive", x=709, y=1114 },
        { slug="depths-of-the-damned/riposte", id="dp_riposte", en="Riposte", cn="还击", desc="+5% Melee Damage after Successful Dodge. Stacking 3 times. Lasts 8 s.", desc_cn="• 成功闪避后 +5% 伤害。\n• 叠加：最多 3 层。\n• 持续：8 秒。", cat="passive", x=1204, y=1586 },
        { slug="depths-of-the-damned/relentless-fervor", id="dp_relentless_fervor", en="Relentless Fervor", cn="狂热不懈", desc="+10% Sprint Speed and -10% Sprint Cost. Sprinting for 1 s grants Slowdown Immunity.", desc_cn="• +10% 冲刺速度 和\n• -10% 冲刺消耗。\n\n冲刺 1 秒后获得：\n• 免疫减速。", cat="passive", x=1204, y=1699 },
        { slug="depths-of-the-damned/unseen-blade", id="dp_unseen_blade", en="Unseen Blade", cn="无形之刃", desc="+20% Damage vs Enemies not targeting you.", desc_cn="对未锁定你的敌人造成的伤害+20%。", cat="passive", x=979, y=979 },
        { slug="depths-of-the-damned/restorative-verses", id="dp_restorative_verses", en="Restorative Verses", cn="治愈诗颂", desc="Martyrdom grants 5% Toughness Replenishment per stack.", desc_cn="• + 每层 殉道 5% 韧性 恢复。", cat="keymod", x=844, y=1879 },
        { slug="depths-of-the-damned/eternal", id="dp_eternal", en="Eternal", cn="永恒", desc="Increase the duration of Inexorable Judgement to 10 s.", desc_cn="将“命定审判”的持续时间延长至10秒。", cat="keymod", x=1114, y=1834 },
        { slug="depths-of-the-damned/blinded-by-blood", id="dp_blinded_by_blood", en="Blinded by Blood", cn="血色迷障", desc="Bleeding enemies increase their damage taken by +15% for 5 s.", desc_cn="", cat="passive", x=484, y=1699 },
        { slug="depths-of-the-damned/punish-impiety", id="dp_punish_impiety", en="Punish Impiety", cn="亵渎必惩", desc="Push followup attacks grant +10% Melee Attack Speed for 5 s.", desc_cn="• 推击后继攻击 5 秒内，+10% 近战攻击速度。", cat="passive", x=574, y=979 },
        { slug="depths-of-the-damned/no-respite", id="dp_no_respite", en="No Respite", cn="刻不容缓", desc="Replenish 10% Stamina on Melee Critical Hit. 1 s Cooldown.", desc_cn="• 近战暴击 恢复 10% 耐力。\n• 冷却：1 秒。", cat="passive", x=664, y=1699 },
        { slug="depths-of-the-damned/providence", id="dp_providence", en="Providence", cn="神恩庇护", desc="+25% Revive Speed. In addition, Allies you Assist / Revive, get +10% Movement Speed and +15% Toughness Damage Reduction for 5 s.", desc_cn="• +25% 救援速度。\n\n你救助或救援的盟友 5 秒内获得：\n• +10% 移动速度 和\n• 15% 韧性伤害减免。", cat="passive", x=844, y=1046 },
        { slug="depths-of-the-damned/abolish-blasphemers", id="dp_abolish_blasphemers", en="Abolish Blasphemers", cn="弑除渎者", desc="+15% Damage vs Elites.", desc_cn="• +15% 对精英敌人伤害。", cat="passive", x=844, y=619 },
        { slug="depths-of-the-damned/hubris", id="dp_hubris", en="Hubris", cn="傲慢", desc="+15% Damage Resistance after Weakspot Kill. Lasts 4 s.", desc_cn="• 弱点 击杀后 4 秒内，+15% 伤害抗性。", cat="passive", x=979, y=1114 },
        { slug="depths-of-the-damned/retaliatory-defence", id="dp_retaliatory_defence", en="Retaliatory Defence", cn="反制护盾", desc="On Block Break, you are no longer Stunned and instead restore 50% Stamina. 12 s Cooldown.", desc_cn="格挡被穿透时不再眩晕，改为恢复 50% 耐力。\n• 冷却：12 秒。", cat="passive", x=1114, y=1114 },
        { slug="depths-of-the-damned/prime-target", id="dp_prime_target", en="Prime Target", cn="头号目标", desc="+10% Damage and replenish 15% Toughness over 5 s, after Elite Kill.", desc_cn="击杀精英敌人后获得：\n• 10% 伤害 和\n• 15% 韧性 在 5 秒内恢复。", cat="passive", x=641, y=1046 },
        { slug="depths-of-the-damned/perfectionist-2", id="dp_perfectionist_2", en="Perfectionist", cn="完美主义者", desc="Restore Ability Cooldown on Stealth Kill. Monstrosities restore 50% , Ogryns restore 30% , and others restore 15% .", desc_cn="隐身状态下击杀敌人可恢复技能冷却时间：巨兽恢复50%，欧格林类敌人恢复30%，其他敌人恢复15%。", cat="abilmod", x=1316, y=1496 },
        { slug="depths-of-the-damned/behind-the-lines", id="dp_behind_the_lines", en="Behind the Lines", cn="敌后行动", desc="Heavy Melee Backstab Kills suppress enemies within 8 m. 5 s Cooldown.", desc_cn="重型近战背刺击杀压制 8 米内敌人。\n• 冷却：5 秒。", cat="passive", x=1024, y=1699 },
        { slug="depths-of-the-damned/on-the-brink", id="dp_on_the_brink", en="On the Brink", cn="危境之际", desc="Martyrdom grants +10% Corruption Resistance per stack.", desc_cn="• 每层 殉道 +10% 腐败抗性。", cat="keymod", x=844, y=1789 },
        { slug="depths-of-the-damned/time-to-kill", id="dp_time_to_kill", en="Time to Kill", cn="杀戮时刻", desc="+50% Melee Backstab Damage. 8 s Cooldown.", desc_cn="• +50% 近战背刺伤害。\n• 冷却：8 秒。", cat="passive", x=1024, y=1586 },
        { slug="depths-of-the-damned/against-the-odds", id="dp_against_the_odds", en="Against the Odds", cn="逆境而上", desc="For every 2 enemies within 5 m, gain +2% Damage and +10% Cleave. Stacks 5 times.", desc_cn="每 2 个在 5 米内的敌人获得：\n• +2% 伤害 和\n• +10% 顺劈攻击。\n• 最多 5 层。", cat="passive", x=776, y=1114 },
        { slug="depths-of-the-damned/the-voice-of-terra-2", id="dp_the_voice_of_terra_2", en="The Voice Of Terra", cn="泰拉之音", desc="While Shooting, replenish 10% Toughness per second.", desc_cn="射击期间每秒恢复10%韧性。", cat="passive", x=664, y=439 },
        { slug="depths-of-the-damned/holy-revenant-2", id="dp_holy_revenant_2", en="Holy Revenant", cn="吊命圣徒", desc="Triggering Until Death knocks back nearby Enemies. While Unkillable, dealing Damage restores Health, up to 25% of Max Health. Mutually exclusive with Zealous Pilgrim.", desc_cn="触发“死战到底”时会击退附近敌人。在不会死亡状态持续期间，造成伤害可恢复生命值，最多恢复至最大生命值的25%。无法与“狂热朝圣者”同时选择。", cat="keymod", x=956, y=799 },
        { slug="depths-of-the-damned/zealous-pilgrim", id="dp_zealous_pilgrim", en="Zealous Pilgrim", cn="狂热朝圣者", desc="Using your Ability grants 5s of Unkillable. Shroudfield: starts on leaving Stealth; Chorus of Spiritual Fortitude: starts on unwielding the relic; Chastise the Wicked / Fury of the Faithful: on ability use.", desc_cn="使用战斗技能后，获得持续5秒的不会死亡效果。隐秘领域：离开隐身时开始；不屈灵魂合唱：收起圣物时开始；惩戒邪恶/忠诚之怒：使用技能时开始。", cat="keymod", x=731, y=799 },
        { slug="depths-of-the-damned/fire-and-fury", id="dp_fire_and_fury", en="Fire And Fury", cn="烈火与狂怒", desc="While Unkillable, weapon attacks apply Burn (up to 12 stacks). Melee attacks apply 3 stacks.", desc_cn="在不会死亡效果持续期间，武器攻击会对敌人施加燃烧（最多12层），近战攻击每次施加3层。", cat="keymod", x=911, y=889 },
        { slug="depths-of-the-damned/out-of-pocket-2", id="dp_out_of_pocket_2", en="Out Of Pocket", cn="自掏腰包", desc="Melee Kills replenish 10% of the missing Ammo in your current Magazine.", desc_cn="近战击杀时，补回当前弹匣已消耗弹药的10%。", cat="passive", x=1114, y=979 },
        { slug="depths-of-the-damned/wait-in-line", id="dp_wait_in_line", en="Wait In Line", cn="排好队", desc="-20% damage taken from ranged attacks.", desc_cn="受到的远程攻击伤害-20%。", cat="passive", x=731, y=529 },
        { slug="depths-of-the-damned/holy-tools", id="dp_holy_tools", en="Holy Tools", cn="神圣武具", desc="+20% Damage on your next Melee Attack, within 5s after activating your Weapon Special.", desc_cn="使用武器特殊动作后5秒内，下一次近战攻击的伤害+20%。", cat="passive", x=709, y=979 },
        { slug="depths-of-the-damned/got-your-back", id="dp_got_your_back", en="Got Your Back", cn="掩护你", desc="Killing an enemy that is targeting an ally, with a melee attack, restores 7.5% Toughness to that ally and an additional 5% to yourself.", desc_cn="以近战攻击击杀正在锁定队友的敌人时，为该队友恢复7.5%韧性，并额外为自己恢复5%韧性。", cat="passive", x=911, y=979 },
        { slug="depths-of-the-damned/purifying-hatred", id="dp_purifying_hatred", en="Purifying Hatred", cn="净化之恨", desc="+15% damage vs Burning or Electrocuted enemies.", desc_cn="对燃烧或遭电击的敌人造成的伤害+15%。", cat="passive", x=574, y=1114 },
        { slug="depths-of-the-damned/risen", id="dp_risen", en="Risen", cn="复生", desc="While Unkillable, each second, gain +5 Max Toughness, stacking 8 times, lasting 5 seconds.", desc_cn="在不会死亡效果持续期间，每秒获得+5最大韧性，最多叠加8次，加成持续5秒。", cat="keymod", x=776, y=889 },
