        { slug="depths-of-the-damned/battle-meditation", id="dp_battle_meditation", en="Battle Meditation", cn="战斗冥想", desc="-10% Peril Generation. 10% chance to Quell 10% Peril on Kill.", desc_cn="", cat="passive", x=799, y=439 },
        { slug="depths-of-the-damned/perfect-timing", id="dp_perfect_timing", en="Perfect Timing", cn="完美时机", desc="+3% Damage for 10 s on Critical Attack. Stacks 5 times.", desc_cn="", cat="passive", x=956, y=439 },
        { slug="depths-of-the-damned/kinetic-flayer", id="dp_kinetic_flayer", en="Kinetic Flayer", cn="动能撕裂者", desc="All Attacks against Specialists, Elites and Monstrosities, have 100% chance on Hit to Brain Rupture the target. This cannot occur while at critical Peril, and has a Cooldown of 12 s.", desc_cn="对专家、精英和巨兽敌人的所有攻击命中时，都有100%几率对目标触发“颅脑崩裂”。处于临界反噬值时无法触发，冷却时间12秒。", cat="passive", x=528, y=686 },
        { slug="depths-of-the-damned/brain-rupture", id="dp_brain_rupture", en="Brain Rupture", cn="颅脑崩裂", desc="Charge up your Psychic Power and release it to deal immense Damage to a Single Enemy. This is an augmented version of Brain Burst dealing +50% Damage.", desc_cn="", cat="blitz", x=596, y=619 },
        { slug="depths-of-the-damned/assail", id="dp_assail", en="Assail", cn="灵能攻击", desc="Throw swift, homing projectiles formed of psychic energy. Less effective versus Carapace Armoured Enemies.", desc_cn="", cat="blitz", x=1001, y=619 },
        { slug="depths-of-the-damned/ethereal-shards", id="dp_ethereal_shards", en="Ethereal Shards", cn="乙太碎片", desc="Projectiles from Assail now pierce additional targets.", desc_cn="• 灵能攻击的投射物现在能穿透额外目标。", cat="passive", x=1092, y=618 },
        { slug="depths-of-the-damned/smite", id="dp_smite", en="Smite", cn="惩戒", desc="Unleash a torrent of Bio-Lightning - a fast, channelled attack that Locks to and Stuns an Enemy while dealing Damage. This spreads to nearby Enemies. Charge to increase Spread rate and Damage.", desc_cn="释放生物闪电洪流：这是一种快速的引导攻击，会锁定并眩晕一名敌人，同时造成伤害；闪电会扩散至附近敌人。蓄力可提高扩散速度和伤害。", cat="blitz", x=799, y=619 },
        { slug="depths-of-the-damned/kinetic-presence", id="dp_kinetic_presence", en="Kinetic Presence", cn="动能释放", desc="+10% Damage against Elite Enemies for you and Allies in Coherency.", desc_cn="你和协同范围内的盟友对精英敌人的伤害+10%。", cat="aura", x=641, y=799 },
        { slug="depths-of-the-damned/kinetic-resonance", id="dp_kinetic_resonance", en="Kinetic Resonance", cn="动能共鸣", desc="Using your Combat Ability makes your Brain Rupture charge +75% faster and generate 50% less Peril for 10 s.", desc_cn="", cat="passive", x=506, y=618 },
        { slug="depths-of-the-damned/seers-presence", id="dp_seers_presence", en="Seer's Presence", cn="先知之眼", desc="+10% Cooldown Reduction on Abilities for you and Allies in Coherency. This is an augmented version of The Quickening .", desc_cn="• 你与协同中的盟友减少+10%冷却。\n• The Quickening的强化版本。\n\n• 不会与其他灵能者的相同光环叠加。", cat="aura", x=799, y=799 },
        { slug="depths-of-the-damned/venting-shriek", id="dp_venting_shriek", en="Venting Shriek", cn="灵能尖啸", desc="Unleashes a wave of warp energy that Staggers Enemies in front of you. Quells 50% Peril. Base Cooldown: 30 s This is an augmented version of Psykinetic's Wrath .", desc_cn="", cat="ability", x=574, y=1361 },
        { slug="depths-of-the-damned/scriers-gaze", id="dp_scriers_gaze", en="Scrier's Gaze", cn="占卜者的注视", desc="Triggers Scrier's Gaze. When entering Scrier's Gaze you Quell 50% Peril as well as gain +10% Damage, +20% Critical Chance, +10% Weakspot Damage, +20% Toughness Damage Reduction, and Suppression Immunity. You also replenish 2.5% Toughness each second. For every second in Scrier's Gaze you gain +1% Damage up to a maximum of +30% . This effect lingers for 10 s after leaving Scrier's Gaze. While in Scrier's Gaze you build up Peril. Build-up is temporarily slowed down by enemy Kills. At 100% Peril, Scrier's Gaze ends. Base Cooldown: 25 s", desc_cn="进入占卜师的凝视，平息50%反噬并获得：\n• +10% 伤害，\n• +20% 暴击率，\n• +10% 弱点伤害，\n• 每秒 2.5% 韧性，\n• +20% 韧性伤害减免，\n• 压制免疫。\n\n处于占卜师的凝视时，每秒获得层数：\n• +1% 伤害，最高+30%。离开占卜师的凝视后，此效果持续10秒。\n\n处于占卜师的凝视时，你会累积反噬。击杀敌人可暂时减缓累积速度。\n达到100%反噬时，能力结束。\n• 基础冷却：25秒。", cat="ability", x=1024, y=1361 },
        { slug="depths-of-the-damned/becalming-eruption", id="dp_becalming_eruption", en="Becalming Eruption", cn="平静迸发", desc="Venting Shriek now decreases Peril Generation by 1% for each Enemy hit, Stacking 25 times. Lasts 5 s.", desc_cn="“宣泄尖啸”每命中一名敌人，使反噬生成降低1%，最多叠加25层，持续5秒。", cat="abilmod", x=484, y=1361 },
        { slug="depths-of-the-damned/creeping-flames", id="dp_creeping_flames", en="Creeping Flames", cn="蔓延火焰", desc="Venting Shriek applies 1 - 6 Stack(s) of Soulblaze to targets Hit based on your current Peril.", desc_cn="", cat="abilmod", x=416, y=1406 },
        { slug="depths-of-the-damned/precognition", id="dp_precognition", en="Precognition", cn="未卜先知", desc="Weakspot Kills count as 1 s spent in Scrier's Gaze . For each second spent in Scrier's Gaze , you now also gain +1% Finesse Damage ( +30% max) which lingers for 10 s after leaving Scrier's Gaze .", desc_cn="处于占卜者的注视超载时，弱点击杀会产生1额外层数。\n• 劈裂时，每次攻击可触发多次。\n\n在占卜者的注视中每秒还可获得：\n• +1% 灵巧伤害，最高+30%，离开占卜者的注视后持续10秒。", cat="abilmod", x=1114, y=1294 },
        { slug="depths-of-the-damned/warp-speed", id="dp_warp_speed", en="Warp Speed", cn="亚空间加速", desc="Scrier's Gaze now also increases your Movement Speed by +20% while active.", desc_cn="", cat="abilmod", x=1114, y=1361 },
        { slug="depths-of-the-damned/quick-shards", id="dp_quick_shards", en="Quick Shards", cn="迅捷碎片", desc="Assail charges Replenish 30% faster.", desc_cn="", cat="passive", x=1068, y=686 },
        { slug="depths-of-the-damned/prescience", id="dp_prescience", en="Prescience", cn="预兆", desc="You and Allies in Coherency gain +5% Critical Hit Chance.", desc_cn="", cat="aura", x=956, y=799 },
        { slug="depths-of-the-damned/wildfire", id="dp_wildfire", en="Wildfire", cn="野火", desc="When an Enemy dies while affected by your Soulblaze, nearby Enemies each gain up to 4 Stacks of Soulblaze. They cannot gain more stacks than the dying Enemy had.", desc_cn="", cat="passive", x=731, y=1181 },
        { slug="depths-of-the-damned/psykinetics-aura", id="dp_psykinetics_aura", en="Psykinetic's Aura", cn="灵能学者光环", desc="Gain 50% Ability Cooldown Regeneration for 3 s when you kill an Elite or Specialist Enemy.", desc_cn="你击杀精英或专家敌人时，技能冷却恢复速度+50%，持续3秒。", cat="abilmod", x=799, y=889 },
        { slug="depths-of-the-damned/mind-in-motion", id="dp_mind_in_motion", en="Mind in Motion", cn="思维活跃", desc="Your Movement Speed is not reduced while Quelling Peril or Reloading. Gain +5% Movement Speed.", desc_cn="平息反噬或装填时移动速度不会降低，并获得+5%移动速度。", cat="passive", x=664, y=1114 },
        { slug="depths-of-the-damned/malefic-momentum", id="dp_malefic_momentum", en="Malefic Momentum", cn="恶意攻势", desc="+5% Damage to Warp Attacks for 10 s after a non-Warp based Kill. Stacks 5 times. +5% Damage to non-Warp Attacks for 10 s after a Warp based Kill. Stacks 5 times.", desc_cn="以非亚空间攻击击杀敌人后，亚空间攻击伤害+5%，持续10秒，最多叠加5层；以亚空间攻击击杀敌人后，非亚空间攻击伤害+5%，持续10秒，最多叠加5层。", cat="passive", x=1001, y=1046 },
        { slug="depths-of-the-damned/reality-anchor", id="dp_reality_anchor", en="Reality Anchor", cn="现实锚点", desc="Scrier's Gaze now also reduces your Peril Generated by -20% and increases Quellling by +30% while active.", desc_cn="“占卜者凝视”激活期间，反噬生成额外降低20%，平息速度提高30%。", cat="abilmod", x=1114, y=1429 },
        { slug="depths-of-the-damned/enfeeble", id="dp_enfeeble", en="Enfeeble", cn="衰弱诅咒", desc="Enemies Electrocuted by you take +10% increased Base Damage from all sources.", desc_cn="", cat="passive", x=888, y=618 },
        { slug="depths-of-the-damned/one-with-the-warp", id="dp_one_with_the_warp", en="One with the Warp", cn="亚空间强化", desc="Gain Toughness Damage Reduction of +10% to +33% based on your current Peril.", desc_cn="根据当前反噬，获得+10%至+33%韧性伤害减免。", cat="passive", x=799, y=1271 },
        { slug="depths-of-the-damned/empathic-evasion", id="dp_empathic_evasion", en="Empathic Evasion", cn="反射闪避", desc="A Critical Hit makes you count as Dodging against Ranged Attacks for 1 s.", desc_cn="", cat="passive", x=934, y=1114 },
        { slug="depths-of-the-damned/anticipation", id="dp_anticipation", en="Anticipation", cn="看破", desc="Increase Effective Dodges by 1 and time considered Dodging by +50% .", desc_cn="", cat="passive", x=934, y=979 },
        { slug="depths-of-the-damned/solidity", id="dp_solidity", en="Solidity", cn="稳固", desc="Increases Quell Speed by 30% .", desc_cn="", cat="passive", x=709, y=1721 },
        { slug="depths-of-the-damned/warp-rider", id="dp_warp_rider", en="Warp Rider", cn="亚空间骑士", desc="Deal up to +20% Damage (increases as your Peril increases).", desc_cn="根据当前反噬，造成的伤害最多提高20%。", cat="passive", x=799, y=1631 },
        { slug="depths-of-the-damned/true-aim", id="dp_true_aim", en="True Aim", cn="精确瞄准", desc="Landing 5 Weakspot Hits grants your next Ranged Attack a guaranteed Critical. Can only trigger once per Attack.", desc_cn="", cat="passive", x=889, y=1541 },
        { slug="depths-of-the-damned/puppet-master", id="dp_puppet_master", en="Puppet Master", cn="傀儡师", desc="75% Radius for your Coherency Aura.", desc_cn="你的协同光环半径+75%。", cat="passive", x=979, y=1721 },
        { slug="depths-of-the-damned/kinetic-deflection", id="dp_kinetic_deflection", en="Kinetic Deflection", cn="动能偏斜", desc="While below critical Peril, Blocking an attack causes you to gain Peril instead of losing Stamina. Gained Peril is 25% of the blocked attacks stamina cost.", desc_cn="", cat="passive", x=889, y=1631 },
        { slug="depths-of-the-damned/telekine-shield", id="dp_telekine_shield", en="Telekine Shield", cn="念力护盾", desc="Spawns a psychic shield in front of you for 17.5 s. The shield blocks Enemy Ranged Attacks, while you and Allies can still shoot through. Base Cooldown: 40 s.", desc_cn="在你前方生成一个持续17.5秒的灵能护盾。护盾会阻挡敌人的远程攻击，但你和盟友仍可穿过护盾射击。基础冷却时间40秒。", cat="ability", x=799, y=1361 },
        { slug="depths-of-the-damned/enervating-threshold", id="dp_enervating_threshold", en="Enervating Threshold", cn="衰弱界线", desc="Telekine Shield has a 20% chance to Electrocute enemies that pass through it. Specialist enemies have a 100% chance to get Electrocuted but also damage the Telekine Shield .", desc_cn="", cat="abilmod", x=731, y=1429 },
        { slug="depths-of-the-damned/sanctuary", id="dp_sanctuary", en="Sanctuary", cn="庇护所", desc="Allies inside your Telekine Shield replenish 10% Toughness each second. When your Telekine Shield dissipates, all Allies inside gain +50% Toughness Damage Reduction for 5 s", desc_cn="• 你的念力护盾内的盟友每秒恢复10%韧性。\n\n• 你的念力护盾消散时，内部的盟友获得+50%韧性伤害减免，持续5秒。\n\n• 若多个球体重叠，此效果叠加。", cat="abilmod", x=866, y=1429 },
        { slug="depths-of-the-damned/telekine-dome", id="dp_telekine_dome", en="Telekine Dome", cn="念力穹顶", desc="Telekine Shield now forms a spherical shield which lasts 25 s, but the Cooldown is increased to 60 s.", desc_cn="", cat="abilmod", x=911, y=1361 },
        { slug="depths-of-the-damned/bolstered-shield", id="dp_bolstered_shield", en="Bolstered Shield", cn="强化护盾", desc="Telekine Shield now holds up to 2 charges.", desc_cn="", cat="abilmod", x=686, y=1361 },
        { slug="depths-of-the-damned/warp-siphon", id="dp_warp_siphon", en="Warp Siphon", cn="亚空间虹吸", desc="Killing an Elite or Specialist Enemy gains you a Warp Charge for 25 s, stacking 4 time(s). Each Stack increases Base Damage by +4% . Your next Combat Ability spends all available Warp Charges to reduce the Cooldown of that Combat Ability by 7.5% per Warp Charge.", desc_cn="击杀精英或专家敌人获得一层“亚空间充能”，持续25秒，最多4层。每层使基础伤害+4%。下一次使用战斗技能时会消耗全部亚空间充能，每层使该战斗技能的冷却时间缩短7.5%。", cat="keystone", x=529, y=1631 },
        { slug="depths-of-the-damned/disrupt-destiny", id="dp_disrupt_destiny", en="Disrupt Destiny", cn="扰动命运", desc="Every second, Enemies within 40 m have a chance of being Marked. Killing a Marked Enemy Replenishes 25% Toughness over 2.5 s, grants +20% Movement Speed for 2.5 s, and adds a Precision Bonus for 5 s. Each Precision Bonus grants +1% Damage, +2% Critical Damage and +2.5% Weakspot Damage. Precision Bonus Stacks 15 times and when the duration ends, one stack is removed and the duration is refreshed.", desc_cn="每秒都会有40米内的敌人有几率被标记。击杀被标记的敌人会在2.5秒内恢复25%韧性、获得+20%移动速度持续2.5秒，并获得一层“精准加成”持续5秒。每层“精准加成”提供+1%伤害、+2%暴击伤害和+2.5%弱点伤害，最多叠加15层；持续时间结束时移除一层，并刷新剩余层数的持续时间。", cat="keystone", x=1069, y=1631 },
        { slug="depths-of-the-damned/empowered-psionics", id="dp_empowered_psionics", en="Empowered Psionics", cn="灵能强化", desc="Kills have a 10% chance to Empower your next Blitz. Empowered Brain Rupture : 100% Peril Cost Reduction 50% Cast time Reduction +50% Damage Empowered Smite : +200% Damage 50% faster spread between enemies Empowered Assail : 100% Peril Cost Reduction. Base Damage increase from 125 to 150 . Does not consume any charges.", desc_cn="击杀敌人有10%几率强化你的下一次闪击。“强化颅脑崩裂”：反噬消耗降低100%，施放时间缩短50%，伤害+50%。“强化惩戒”：伤害+200%，在敌人之间的扩散速度提高50%。“强化灵能攻击”：反噬消耗降低100%，基础伤害由125提高至150，且不消耗充能次数。", cat="keystone", x=799, y=1811 },
        { slug="depths-of-the-damned/inner-tranquility", id="dp_inner_tranquility", en="Inner Tranquility", cn="平心静气", desc="-8% Peril Generation Reduction for each Warp Charge.", desc_cn="每层“亚空间充能”使反噬生成降低8%。", cat="keymod", x=461, y=1564 },
        { slug="depths-of-the-damned/essence-harvest", id="dp_essence_harvest", en="Essence Harvest", cn="吸精夺萃", desc="Replenish 30% Toughness over 5 s on gaining Warp Charge. Gaining a new Warp Charge during this time resets the timer.", desc_cn="", cat="keymod", x=461, y=1699 },
        { slug="depths-of-the-damned/bio-lodestone", id="dp_bio_lodestone", en="Bio-Lodestone", cn="生物磁石", desc="Increases the chance to gain Empowered Psionics on Kill from 10% to 15% .", desc_cn="击杀时获得“灵能强化”的几率由10%提高至15%。", cat="keymod", x=731, y=1879 },
        { slug="depths-of-the-damned/psychic-leeching", id="dp_psychic_leeching", en="Psychic Leeching", cn="吸血闪电", desc="Using your Blitz while Empowered Psionics is active replenishes 20% Toughness to you and Allies in Coherency.", desc_cn="“灵能强化”激活期间使用闪击时，为你和协同范围内的盟友恢复20%韧性。", cat="keymod", x=799, y=1901 },
        { slug="depths-of-the-damned/overpowering-souls", id="dp_overpowering_souls", en="Overpowering Souls", cn="吞灵强击", desc="Guaranteed chance to gain Empowered Psionics on Elite Kills.", desc_cn="• 击杀精英敌人时，保证获得灵能强化。", cat="keymod", x=866, y=1879 },
        { slug="depths-of-the-damned/perfectionism", id="dp_perfectionism", en="Perfectionism", cn="完美主义", desc="Maximum Precision Bonus stacks are increased from 15 to 25 .", desc_cn="", cat="keymod", x=1159, y=1699 },
        { slug="depths-of-the-damned/purloin-providence", id="dp_purloin_providence", en="Purloin Providence", cn="盗窃天命", desc="Killing Enemies Marked by Disrupt Destiny have a 100% chance to instantly Quell 5% of your Peril.", desc_cn="击杀被“扰动命运”标记的敌人时，有100%几率立即平息5%反噬。", cat="keymod", x=1159, y=1631 },
        { slug="depths-of-the-damned/lingering-influence", id="dp_lingering_influence", en="Lingering Influence", cn="持久影响", desc="Increase the duration of Disrupt Destiny from 5 s to 10 s.", desc_cn="", cat="keymod", x=1159, y=1564 },
        { slug="depths-of-the-damned/charged-up", id="dp_charged_up", en="Charged Up", cn="充能完毕", desc="You can now hold up to 3 Stacks of Empowered Psionics .", desc_cn="• 现在最多可储存3层灵能强化。", cat="keymod", x=799, y=1991 },
        { slug="depths-of-the-damned/in-fire-reborn", id="dp_in_fire_reborn", en="In Fire Reborn", cn="涅槃", desc="Killing an Enemy with Soulblaze has a 10% chance to grant you a Warp Charge.", desc_cn="", cat="keymod", x=371, y=1586 },
        { slug="depths-of-the-damned/psychic-vampire", id="dp_psychic_vampire", en="Psychic Vampire", cn="灵能吸血鬼", desc="Whenever you or an ally in Coherency kill an Enemy, you have a 4% chance to gain a Warp Charge.", desc_cn="", cat="keymod", x=371, y=1676 },
        { slug="depths-of-the-damned/warp-battery", id="dp_warp_battery", en="Warp Battery", cn="亚空间电池", desc="Can store up to 6 Warp Charges.", desc_cn="", cat="keymod", x=439, y=1631 },
        { slug="depths-of-the-damned/cruel-fortune", id="dp_cruel_fortune", en="Cruel Fortune", cn="残忍命运", desc="Weakspot Kills grant 2 additional Stacks of Disrupt Destiny .", desc_cn="弱点击杀额外获得2层“扰动命运”。", cat="keymod", x=1249, y=1631 },
        { slug="depths-of-the-damned/warp-unbound", id="dp_warp_unbound", en="Warp Unbound", cn="亚空间突破", desc="Scrier's Gaze now also prevents overloading from Perils of the Warp, during its lingering effect.", desc_cn="", cat="abilmod", x=1204, y=1361 },
        { slug="depths-of-the-damned/lightning-speed", id="dp_lightning_speed", en="Lightning Speed", cn="迅雷之势", desc="10% Melee Attack Speed.", desc_cn="• +10% 攻击速度。", cat="passive", x=866, y=1181 },
        { slug="depths-of-the-damned/warp-splitting", id="dp_warp_splitting", en="Warp Splitting", cn="亚空间分裂", desc="Up to +100% Cleave, based on Peril.", desc_cn="", cat="passive", x=866, y=1046 },
        { slug="depths-of-the-damned/souldrinker", id="dp_souldrinker", en="Souldrinker", cn="汲魂者", desc="Killing an Enemy with Soulblaze restores 15% Toughness over 5 s and grants 5% Critical Hit Chance for the duration.", desc_cn="", cat="passive", x=731, y=1046 },
        { slug="depths-of-the-damned/by-crack-of-bone", id="dp_by_crack_of_bone", en="By Crack of Bone", cn="骨折后遗症", desc="Melee Weakspot Kills Quell 10% Peril and Reduce further Peril Generation by 20% for 4 s.", desc_cn="", cat="passive", x=1001, y=1181 },
        { slug="depths-of-the-damned/empyric-resolve", id="dp_empyric_resolve", en="Empyric Resolve", cn="亚空间意志", desc="-40% Peril Generation. -30% Toughness Replenished.", desc_cn="", cat="passive", x=619, y=1631 },
        { slug="depths-of-the-damned/penetration-of-the-soul", id="dp_penetration_of_the_soul", en="Penetration of the Soul", cn="灵魂穿透", desc="Up to +20% Rending on Warp-Attacks, based on Peril.", desc_cn="根据反噬，亚空间攻击最多获得+20%撕裂。", cat="passive", x=619, y=1541 },
        { slug="depths-of-the-damned/surety-of-arms", id="dp_surety_of_arms", en="Surety of Arms", cn="武器在手，信心我有。", desc="30% Reload Speed while below 80% Peril. On Reload generate up to 15% Peril based on the Percentage of the Clip Restored.", desc_cn="反噬低于80%时，装填速度+30%。装填时根据恢复的弹匣比例最多生成15%反噬。", cat="passive", x=979, y=1541 },
        { slug="depths-of-the-damned/charged-strike", id="dp_charged_strike", en="Charged Strike", cn="蓄力打击", desc="Your Heavy Melee Attacks electrocute enemies hit, damaging them.", desc_cn="", cat="passive", x=708, y=618 },
        { slug="depths-of-the-damned/crystalline-will", id="dp_crystalline_will", en="Crystalline Will", cn="结晶意志", desc="+100% Overload Explosion Damage and +25% Overload Explosion Radius. Overloading through Perils of the Warp no longer knocks you down, but you still take the appropriate Corruption Damage. If the explosion kills an Elite enemy, you don't take any Corruption Damage.", desc_cn="", cat="passive", x=619, y=1721 },
        { slug="depths-of-the-damned/channeled-force", id="dp_channeled_force", en="Channeled Force", cn="灵能引导", desc="+20% Damage to Force Staff's Primary Attacks after Fully Charged Force Staff Secondary Attacks. Lasts 5 s. +10% Damage to Force Staff's Secondary Attacks after Force Staff Primary Attack. Lasts 5 s.", desc_cn="", cat="passive", x=596, y=1046 },
        { slug="depths-of-the-damned/empyric-shock", id="dp_empyric_shock", en="Empyric Shock", cn="亚空间震波", desc="6% Warp-Damage Taken by victims of your Force Staff's Primary Attack. Max Stacks 5 . Lasts 10 s.", desc_cn="", cat="passive", x=596, y=1181 },
        { slug="depths-of-the-damned/warp-expenditure-2", id="dp_warp_expenditure_2", en="Warp Expenditure", cn="亚空间耗费", desc="Melee Weakspot Kills restore 15% Toughness over 3 s. Successful Melee Attacks restore 2.5% Toughness instantly.", desc_cn="近战弱点击杀会在3秒内恢复15%韧性。成功的近战攻击会立即恢复2.5%韧性。", cat="passive", x=844, y=371 },
        { slug="depths-of-the-damned/warp-rupture-2", id="dp_warp_rupture_2", en="Warp Rupture", cn="亚空间爆发", desc="Venting Shriek decreases the Damage Dealt by enemies hit by 10% and increases their Damage Taken by 10% for 8 s.", desc_cn="", cat="abilmod", x=416, y=1316 },
        { slug="depths-of-the-damned/toughness-boost-51f63e01", id="dp_toughness_boost_51f63e01", en="Toughness Boost", cn="韧性增幅", desc="+25 Toughness.", desc_cn="韧性+25。", cat="stat", x=799, y=529 },
        { slug="depths-of-the-damned/toughness-boost-e8d6645b", id="dp_toughness_boost_e8d6645b", en="Toughness Boost", cn="韧性增幅", desc="+25 Toughness.", desc_cn="韧性+25。", cat="stat", x=799, y=1541 },
        { slug="depths-of-the-damned/toughness-damage-reduction-d116b71e", id="dp_toughness_damage_reduction_d116b71e", en="Toughness Damage Reduction", cn="韧性减伤", desc="+10% Toughness Damage Reduction.", desc_cn="韧性伤害减免+10%。", cat="stat", x=799, y=709 },
        { slug="depths-of-the-damned/just-a-dream", id="dp_just_a_dream", en="Just a Dream", cn="如梦似幻", desc="While below Critical Peril, 25% of Damage Taken is converted into Peril.", desc_cn="", cat="passive", x=664, y=979 },
        { slug="depths-of-the-damned/immaterial-focus", id="dp_immaterial_focus", en="Immaterial Focus", cn="无形专注", desc="+10% Damage Resistance, in addition, while at Critical Peril, and for 4 s afterwards, you are Stun Immune.", desc_cn="获得+10%伤害抗性。此外，当反噬达到临界状态时以及之后4秒内，你免疫眩晕。", cat="passive", x=799, y=979 },
