        { slug="depths-of-the-damned/lynchpin", id="dp_lynchpin", en="Lynchpin", cn="关键人物", desc="+100% Coherency Toughness Regeneration.", desc_cn="协同韧性恢复速度+100%。", cat="passive", x=1001, y=484 },
