        { slug="depths-of-the-damned/coward-culling", id="dp_coward_culling", en="Coward Culling", cn="优胜劣汰", desc="+20% Damage against Suppressed Enemies for you and Allies in Coherency. +25% Suppression dealt.", desc_cn="你和协同范围内的盟友对受压制的敌人造成+20%伤害；造成的压制效果+25%。", cat="aura", x=1091, y=1339 },
        { slug="depths-of-the-damned/stay-close", id="dp_stay_close", en="Stay Close!", cn="跟紧我！", desc="+20% Toughness Replenishment for you and Allies in Coherency.", desc_cn="你和协同范围内的盟友韧性恢复量+20%。", cat="aura", x=821, y=1339 },
        { slug="depths-of-the-damned/slam", id="dp_slam", en="Slam", cn="猛击", desc="+25% Impact bonus on Melee Attacks. Staggering an enemy with a Melee Attack replenishes 5% Stamina. 0.75 s Cooldown.", desc_cn="• +25% 近战攻击的冲击加成。\n\n• 近战攻击使敌人踉跄 后，恢复 5% 耐力。\n\n• 冷却：0.75 秒。", cat="passive", x=821, y=1249 },
        { slug="depths-of-the-damned/soften-them-up", id="dp_soften_them_up", en="Soften Them Up", cn="削弱敌人", desc="Enemies damaged by your Melee Attacks take +15% more Damage for 5 s.", desc_cn="被你的近战攻击命中的敌人额外受到15%伤害，持续5秒。", cat="passive", x=686, y=394 },
        { slug="depths-of-the-damned/bombs-away", id="dp_bombs_away", en="Bombs Away!", cn="投弹完毕！", desc="Throw a box of grenades with great strength and enthusiasm to deal high Damage to a Single Enemy. Hitting an Enemy causes the box to break open, releasing 6 grenades around the target. This is an augmented version of Big Box of Hurt .", desc_cn="", cat="blitz", x=1046, y=664 },
        { slug="depths-of-the-damned/frag-bomb", id="dp_frag_bomb", en="Frag Bomb", cn="破片炸弹", desc="Throw an Ogryn-sized (the only proper kind!) frag grenade with a 16 m blast radius, dealing increased Damage at the centre. Human-sized, Non-Captain enemies, are always killed.", desc_cn="", cat="blitz", x=821, y=664 },
        { slug="depths-of-the-damned/crunch", id="dp_crunch", en="Crunch!", cn="嘎嘎！", desc="Up to +30% Damage bonus & +30% Impact bonus to your charged Melee Attack, based on charge time.", desc_cn="根据蓄力时间，你的蓄力近战攻击最多获得+30%伤害和+30%冲击。", cat="passive", x=461, y=1496 },
        { slug="depths-of-the-damned/batter", id="dp_batter", en="Batter", cn="重殴", desc="Inflict +1 Stacks of Bleed on Melee Hit. Increased to +4 on Heavy Melee Hit.", desc_cn="近战命中施加1层流血；重型近战命中改为施加4层。", cat="passive", x=641, y=1339 },
        { slug="depths-of-the-damned/hard-knocks", id="dp_hard_knocks", en="Hard Knocks", cn="沉重打击", desc="Enemies staggered by your Melee Attacks take +15% more Melee Damage for 5 s.", desc_cn="被你的近战攻击打至踉跄的敌人，在5秒内额外受到15%近战伤害。", cat="passive", x=731, y=1676 },
        { slug="depths-of-the-damned/pacemaker", id="dp_pacemaker", en="Pacemaker", cn="领跑者", desc="Hitting 3 or more Enemies with a single Attack grants +15% Reload Speed on your next Reload.", desc_cn="单次攻击命中3名或更多敌人后，你的下一次装填速度+15%。", cat="passive", x=1001, y=1496 },
        { slug="depths-of-the-damned/ammo-stash", id="dp_ammo_stash", en="Ammo Stash", cn="弹药储存包", desc="Increase your ammo reserve by +25% .", desc_cn="• +25% 最大备用弹药，向下取整计算。", cat="passive", x=1091, y=1249 },
        { slug="depths-of-the-damned/mobile-emplacement", id="dp_mobile_emplacement", en="Mobile Emplacement", cn="机动部署", desc="You take 25% reduced Damage while bracing or shooting a Ranged Weapon.", desc_cn="射击或瞄准远程武器时：\n• +25% 伤害减少。", cat="passive", x=1001, y=866 },
        { slug="depths-of-the-damned/burst-limiter-override", id="dp_burst_limiter_override", en="Burst Limiter Override", cn="爆限超载", desc="15% chance of triggering Lucky Bullet and not consuming Ammo when making Ranged Attacks. In addition, gain +2% Ranged Damage on Ranged Kills. Max Stacks 10 . Lasts 10 s.", desc_cn="进行远程攻击时有15%几率触发“幸运子弹”，不消耗弹药。此外，远程击杀会使远程伤害提高2%，最多叠加10层，持续10秒。", cat="keystone", x=1091, y=1654 },
        { slug="depths-of-the-damned/wont-give-in", id="dp_wont_give_in", en="Won't Give In", cn="绝不屈服", desc="+20% Damage Reduction for each Knocked Down or Incapacitated Ally within 20 metres.", desc_cn="• +20% 伤害减少，\n每名 20 米内倒地或失能的队友提供一份。", cat="passive", x=911, y=1676 },
        { slug="depths-of-the-damned/feel-no-pain", id="dp_feel_no_pain", en="Feel No Pain", cn="麻木", desc="You are blessed with 10 Stacks of Feel No Pain. Each Stack grants +3% Toughness Replenishment and +3% Damage Reduction. Taking Damage removes one stack. Stacks are restored every 2 s.", desc_cn="你拥有10层“麻木”。每层提供+3%韧性恢复量和+3%伤害减免。受到伤害会移除一层；每2秒恢复一层。", cat="keystone", x=821, y=1744 },
        { slug="depths-of-the-damned/implacable", id="dp_implacable", en="Implacable", cn="利刃出鞘", desc="+15% Damage Reduction while charging Melee Attacks.", desc_cn="蓄力近战攻击时：\n• +15% 伤害减少。", cat="passive", x=461, y=1586 },
        { slug="depths-of-the-damned/delight-in-destruction", id="dp_delight_in_destruction", en="Delight in Destruction", cn="毁灭之乐", desc="+5% Damage Resistance per Bleeding Enemy in Melee range. Stacks 6 times.", desc_cn="近战范围内每有一名正在流血的敌人，获得+5%伤害抗性，最多叠加6层。", cat="passive", x=551, y=1519 },
        { slug="depths-of-the-damned/heavy-hitter", id="dp_heavy_hitter", en="Heavy Hitter", cn="重拳出击", desc="+3% Melee Damage for 7.5 s on Melee Attack Hit. Stacks 8 times. Gain 2 Stacks on Heavy Attack Hit.", desc_cn="近战攻击命中后，近战伤害+3%，持续7.5秒，最多叠加8层。重攻击命中时获得2层。", cat="keystone", x=551, y=1654 },
        { slug="depths-of-the-damned/just-getting-started-2", id="dp_just_getting_started_2", en="Just Getting Started!", cn="热身完毕", desc="While Heavy Hitter is at 8 Stacks, gain +10% Attack Speed.", desc_cn="“重拳出击”达到8层时，攻击速度+10%。", cat="keymod", x=551, y=1744 },
        { slug="depths-of-the-damned/unstoppable", id="dp_unstoppable", en="Unstoppable", cn="越战越勇", desc="Heavy Hitter also grants +15% Toughness replenished from Melee Kills for each stack.", desc_cn="“重拳出击”每层额外使近战击杀恢复的韧性提高15%。", cat="keymod", x=619, y=1744 },
        { slug="depths-of-the-damned/pained-outburst", id="dp_pained_outburst", en="Pained Outburst", cn="痛楚爆发", desc="When Feel No Pain reaches 5 stacks or below, you push back Enemies and Replenish +50% Toughness. This effect can occur once every 30 s.", desc_cn="“不痛不痒”的层数降至5层或以下时，将周围敌人推开并恢复50%韧性。该效果每30秒最多触发一次。", cat="keymod", x=754, y=1811 },
        { slug="depths-of-the-damned/strongest", id="dp_strongest", en="Strongest!", cn="最强壮！", desc="Pushing Enemies restores one stack of Feel No Pain .", desc_cn="", cat="keymod", x=889, y=1811 },
        { slug="depths-of-the-damned/toughest", id="dp_toughest", en="Toughest!", cn="最坚韧！", desc="Feel No Pain grants +2.5% Toughness Replenishment per stack.", desc_cn="", cat="keymod", x=821, y=1856 },
        { slug="depths-of-the-damned/maximum-firepower", id="dp_maximum_firepower", en="Maximum Firepower", cn="最大火力", desc="+100% Ability Cooldown Regeneration for 2.5 s when Lucky Bullet triggers.", desc_cn="触发“幸运子弹”时，技能冷却恢复速度+100%，持续2.5秒。", cat="keymod", x=1091, y=1744 },
        { slug="depths-of-the-damned/good-shootin", id="dp_good_shootin", en="Good Shootin'", cn="好枪法", desc="The shot that triggers Lucky Bullet is a guaranteed Critical (if it Hits).", desc_cn="触发幸运子弹 的射击，\n若命中则必定暴击。", cat="keymod", x=1159, y=1744 },
        { slug="depths-of-the-damned/toughness-damage-reduction-e0dd7125", id="dp_toughness_damage_reduction_e0dd7125", en="Toughness Damage Reduction", cn="韧性减伤", desc="+10% Toughness Damage Reduction.", desc_cn="韧性伤害减免+10%。", cat="stat", x=821, y=754 },
        { slug="depths-of-the-damned/bruiser", id="dp_bruiser", en="Bruiser", cn="格斗兵", desc="50% Ability Cooldown Regeneration for 4 s after you or an Ally in Coherency kills an Elite Enemy.", desc_cn="你或协同范围内的盟友击杀精英敌人后，技能冷却恢复速度+50%，持续4秒。", cat="passive", x=821, y=1429 },
        { slug="depths-of-the-damned/get-stuck-in", id="dp_get_stuck_in", en="Get Stuck In", cn="全神贯注", desc="On activating your Combat Ability, you and Allies in Coherency gain +20% Movement Speed and are also Immune to Stuns & Suppression for 6 s.", desc_cn="激活战斗技能时，你和协同范围内的盟友获得+20%移动速度，并免疫眩晕与压制，持续6秒。", cat="passive", x=911, y=1586 },
        { slug="depths-of-the-damned/too-stubborn-to-die", id="dp_too_stubborn_to_die", en="Too Stubborn to Die", cn="坚韧不屈", desc="+100% Toughness Replenishment while below 50% Health.", desc_cn="生命值低于50%时，韧性恢复量+100%。", cat="passive", x=641, y=1496 },
        { slug="depths-of-the-damned/no-stopping-me", id="dp_no_stopping_me", en="No Stopping Me!", cn="谁敢拦我！", desc="Become Uninterruptible while charging Heavy Melee Attacks. Remove 100% of Heavy Melee Attack Movement Speed penalties.", desc_cn="蓄力重型近战攻击时不会被打断，并移除100%的重型近战攻击移动速度惩罚。", cat="passive", x=461, y=1676 },
        { slug="depths-of-the-damned/massacre", id="dp_massacre", en="Massacre", cn="屠杀", desc="Killing an Enemy grants +2% Critical Chance for 12 s. Stacks 8 times.", desc_cn="击杀敌人后暴击率+2%，持续12秒，最多叠加8层。", cat="passive", x=1181, y=1586 },
        { slug="depths-of-the-damned/payback-time", id="dp_payback_time", en="Payback Time", cn="报复时间", desc="+15% Damage for 5 s after a Successful Dodge, or being Hit by an Attack.", desc_cn="成功闪避或被攻击命中后，伤害+15%，持续5秒。", cat="passive", x=956, y=394 },
        { slug="depths-of-the-damned/dominate", id="dp_dominate", en="Dominate", cn="主宰", desc="+15% Rending for 10 s on Elite Kill.", desc_cn="击杀精英敌人后获得+15%撕裂，持续10秒。", cat="passive", x=641, y=1586 },
        { slug="depths-of-the-damned/big-boom", id="dp_big_boom", en="Big Boom", cn="大爆炸", desc="Increase explosion radius by +27.5% .", desc_cn="", cat="passive", x=1181, y=1496 },
        { slug="depths-of-the-damned/unstoppable-momentum", id="dp_unstoppable_momentum", en="Unstoppable Momentum", cn="势不可挡", desc="+20% Movement Speed for 3 s on Ranged Kill.", desc_cn="远程击杀后移动速度+20%，持续3秒。", cat="passive", x=1001, y=1586 },
        { slug="depths-of-the-damned/loyal-protector", id="dp_loyal_protector", en="Loyal Protector", cn="忠诚守护者", desc="Taunt Enemies within 12 m, making them attack only you for 15 s. The effect repeats after 3 s, and after 6 s. Base Cooldown: 50 s", desc_cn="嘲讽 12 米范围内的敌人，\n使其只攻击你 15 秒。\n效果分别在 3 秒后和 6 秒后重复。\n\n基础冷却：50 秒。", cat="ability", x=821, y=1069 },
        { slug="depths-of-the-damned/indomitable", id="dp_indomitable", en="Indomitable", cn="不屈不挠", desc="Charge forward with great force, knocking back and Staggering Enemies. Gain +25% Attack Speed and +25% Movement Speed for 5 s. The charge stops on collision with Monstrosities. Base Cooldown: 25 s. This is an augmented version of Bull Rush with +100% charge distance.", desc_cn="向前强力冲锋，击退并使敌人踉跄。获得+25%攻击速度和+25%移动速度，持续5秒。撞上巨兽时会停止冲锋。基础冷却时间25秒。该技能是“蛮牛冲撞”的强化版本，冲锋距离提高100%。", cat="ability", x=551, y=1114 },
        { slug="depths-of-the-damned/point-blank-barrage", id="dp_point_blank_barrage", en="Point-Blank Barrage", cn="贴身火力", desc="Swaps to and reloads your Ranged Weapon. You have +25% Rate of Fire, +65% Reload Speed, 50% Reduced Braced Movement Speed penalties, and gain +15% Close Range Damage for the next 12 s. 50% of Ammo consumed while active is returned to your Reserve once finished. Base Cooldown: 60 s", desc_cn="切换至远程武器并完成装填。接下来12秒内，射速+25%、装填速度+65%，架枪时的移动速度惩罚降低50%，近距离伤害+15%。效果结束时，激活期间消耗弹药的50%会返还至弹药储备。基础冷却时间60秒。", cat="ability", x=1091, y=1114 },
        { slug="depths-of-the-damned/stomping-boots", id="dp_stomping_boots", en="Stomping Boots", cn="跺杀之靴", desc="Replenish +10% Toughness per Enemy Hit with Indomitable .", desc_cn="• 每次 不屈不挠 命中敌人，恢复 +10% 韧性。", cat="abilmod", x=439, y=1114 },
        { slug="depths-of-the-damned/pulverise", id="dp_pulverise", en="Pulverise", cn="粉碎", desc="Apply 5 stacks of Bleed on Enemies hit by Indomitable .", desc_cn="", cat="abilmod", x=484, y=1181 },
        { slug="depths-of-the-damned/just-getting-started", id="dp_just_getting_started", en="Go Again!", cn="再来", desc="Staggering an Enemy replenishes 1.5% Cooldown of Loyal Protector.", desc_cn="使敌人踉跄可恢复“忠诚护卫”1.5%的冷却时间。", cat="abilmod", x=889, y=1181 },
        { slug="depths-of-the-damned/hail-of-fire", id="dp_hail_of_fire", en="Hail of Fire", cn="枪林弹雨", desc="+15% Rending and +15% Damage to your Ranged Attacks while Point-Blank Barrage is active.", desc_cn="“近距离火力压制”激活期间，你的远程攻击获得+15%撕裂和+15%伤害。", cat="abilmod", x=1294, y=1114 },
        { slug="depths-of-the-damned/light-em-up", id="dp_light_em_up", en="Light 'em Up", cn="集火射击", desc="Ranged Attacks apply 4 Stacks of Burn while Point-Blank Barrage is active. Max Stacks 16 .", desc_cn="“近距离火力压制”激活期间，远程攻击施加4层燃烧，最多16层。", cat="abilmod", x=1271, y=1181 },
        { slug="depths-of-the-damned/valuable-distraction", id="dp_valuable_distraction", en="Valuable Distraction", cn="重要干扰", desc="Enemies affected by Loyal Protector take +20% Base Damage from all sources.", desc_cn="", cat="abilmod", x=754, y=1181 },
        { slug="depths-of-the-damned/no-pushover", id="dp_no_pushover", en="No Pushover", cn="睚眦必报", desc="Your Pushes have +250% Stagger. Can only trigger once every 8 s.", desc_cn="• 250% 推击的踉跄加成。\n• 每 8 秒最多触发一次。", cat="passive", x=731, y=1586 },
        { slug="depths-of-the-damned/bullet-bravado", id="dp_bullet_bravado", en="Bullet Bravado", cn="壮胆子弹", desc="While Point-Blank Barrage is active, Replenish +2.5% Toughness for every shot fired and +15% Toughness on each reload.", desc_cn="“贴身火力”激活期间，每射击一发恢复2.5%韧性，每次装填恢复15%韧性。", cat="abilmod", x=1204, y=1114 },
        { slug="depths-of-the-damned/big-friendly-rock", id="dp_big_friendly_rock", en="Big Friendly Rock", cn="投石问路", desc="Toss a big rock or hunk of junk at a Single Enemy. Reduced effectiveness against Carapace Armoured Enemies and Unyielding Enemies. You pick up a new rock every 45 s and can hold up to 4 rocks at a time.", desc_cn="", cat="blitz", x=596, y=664 },
        { slug="depths-of-the-damned/attention-seeker", id="dp_attention_seeker", en="Attention Seeker", cn="渴求关注", desc="Blocking or Pushing Enemies Taunts them for 8 s.", desc_cn="推击、格挡近战攻击或用盾牌格挡远程攻击时，\n嘲讽敌人，迫使其攻击你。\n\n嘲讽远程敌人，迫使其进入近战。\n• 对枪手、收割者、巨兽无效。\n• 对队长和双子有效。\n\n• 持续 8 秒。", cat="passive", x=731, y=1496 },
        { slug="depths-of-the-damned/trample", id="dp_trample", en="Trample", cn="践踏", desc="For each Enemy hit by Bull Rush you gain a Stack of Trample. Trample increases Base Damage by +2.5% for 10 s. Max Stacks 20 .", desc_cn="被 Bull Rush 命中的每个敌人，\n可获得一层践踏。\n\n每层在 10 秒内提供：\n• +2.5% 基础伤害。\n• 最多 20 层。", cat="abilmod", x=619, y=1181 },
        { slug="depths-of-the-damned/bulletstorm-2", id="dp_bulletstorm_2", en="Bulletstorm", cn="子弹风暴", desc="+15% Ranged Damage to you and Allies in Coherency on Lucky Bullet. Lasts 8 s.", desc_cn="触发“幸运子弹”时，你和协同范围内的盟友获得+15%远程伤害，持续8秒。", cat="keymod", x=1136, y=1811 },
        { slug="depths-of-the-damned/no-hurting-friends-2", id="dp_no_hurting_friends_2", en="No Hurting Friends!", cn="相亲相爱好伙伴！", desc="+2% Strength on Damage Taken by you or Allies in Coherency. 5 Max Stacks. Lasts 10 s. +15% Toughness Damage Reduction on Max Stacks.", desc_cn="你或协同范围内的盟友受到伤害时，获得+2%强度，最多叠加5层，持续10秒。达到最大层数时，再获得+15%韧性伤害减免。", cat="passive", x=821, y=1654 },
        { slug="depths-of-the-damned/no-pain-2", id="dp_no_pain_2", en="No Pain!", cn="一点都不痛！", desc="Loyal Protector and its Repeats, Replenish 10% Toughness and an additional 0.5% each 1s per enemy affected, up to 10% , for 3 s.", desc_cn="“忠诚护卫”及其重复触发每次恢复10%韧性；每影响一名敌人，之后3秒内每1秒额外恢复0.5%韧性，额外恢复最高10%。", cat="abilmod", x=821, y=1159 },
        { slug="depths-of-the-damned/that-one-didnt-count-2", id="dp_that_one_didnt_count_2", en="That One Didn't Count", cn="那下不算！", desc="Big Friendly Rock Replenishes a Charge if you hit a Weakspot or hit no enemies. 5 s Cooldown.", desc_cn="“友好大石头”若命中弱点或未命中任何敌人，会恢复一次充能。冷却时间5秒。", cat="passive", x=596, y=754 },
        { slug="depths-of-the-damned/for-the-liluns-2", id="dp_for_the_liluns_2", en="For the Lil'Uns", cn="为了小子们", desc="On Ally getting Toughness Broken, gain +10% Strength, and +25% Toughness Damage Reduction for 10 s. 20 s Cooldown. On Ally getting Knocked Down, gain Stun Immunity, and +25% Revive Speed for 10 s.", desc_cn="盟友韧性被击破时，你获得+10%强度和+25%韧性伤害减免，持续10秒，冷却20秒。盟友倒地时，你获得眩晕免疫和+25%救援速度，持续10秒。", cat="passive", x=911, y=1339 },
        { slug="depths-of-the-damned/cant-hit-meagain-2", id="dp_cant_hit_meagain_2", en="Can't Hit Me...Again", cn="休想再打中我......", desc="+20% Damage Resistance vs Ranged for 2.5 s after getting hit by a Ranged Attack. 4 s Cooldown.", desc_cn="受到远程攻击命中后，对远程伤害的伤害抗性+20%，持续2.5秒。冷却时间4秒。", cat="passive", x=889, y=956 },
        { slug="depths-of-the-damned/focused-fighter-2", id="dp_focused_fighter_2", en="Focused Fighter", cn="专注斗士", desc="+4% Damage Resistance from Melee Attacks on Successful Melee Attack. Stacks 5 times. Stacks are removed upon taking Damage from a Melee Attack.", desc_cn="成功近战攻击后，获得+4%对近战攻击的伤害抗性，最多叠加5层。受到近战攻击伤害时移除这些层数。", cat="passive", x=641, y=866 },
        { slug="depths-of-the-damned/brutish-strength-2", id="dp_brutish_strength_2", en="Brutish Strength", cn="蛮横之力", desc="4 Stacks of Brittleness on Push.", desc_cn="", cat="passive", x=731, y=1339 },
        { slug="depths-of-the-damned/fire-away-2", id="dp_fire_away_2", en="Fire Away", cn="火力全开", desc="Your Explosions apply 1 Stack(s) of Burn. 2 Stack(s) if close range. Max Stacks 8 .", desc_cn="你的爆炸会施加1层燃烧；近距离爆炸施加2层。最多8层。", cat="passive", x=1181, y=1339 },
        { slug="depths-of-the-damned/unbreakable-2", id="dp_unbreakable_2", en="Unbreakable", cn="坚不可摧", desc="Your Perfect Blocks can block all Melee Attacks. On Perfect Block gain +20% Melee Damage on next Attack.", desc_cn="你的完美格挡可以挡下所有近战攻击。成功完美格挡后，下一次攻击的近战伤害+20%。", cat="passive", x=911, y=1496 },
        { slug="depths-of-the-damned/pumped-up-2", id="dp_pumped_up_2", en="Pumped Up", cn="士气高昂", desc="+12.5% Damage Resistance while above 75% Stamina.", desc_cn="耐力高于75%时，伤害抗性+12.5%。", cat="passive", x=754, y=866 },
        { slug="depths-of-the-damned/lucky-streak-2", id="dp_lucky_streak_2", en="Lucky Streak", cn="好运连连", desc="+75% Critical Strike Damage.", desc_cn="暴击伤害+75%。", cat="passive", x=1181, y=1676 },
