        { slug="depths-of-the-damned/beat-them-back-2", id="dp_beat_them_back_2", en="Beat Them Back", cn="击溃他们", desc="+15% Melee Damage on Successful Heavy Melee Attack. Lasts 5 s.", desc_cn="成功的重型近战攻击后，近战伤害+15%，持续5秒。", cat="passive", x=461, y=1339 },
        { slug="depths-of-the-damned/concentrate-2", id="dp_concentrate_2", en="Concentrate", cn="专注", desc="+60% Sway Reduction, +20% Spread Reduction, and +15% Recoil Reduction while bracing your Ranged Weapon, but lose 0.5 Stamina per second.", desc_cn="架枪使用远程武器时，武器晃动降低60%、散布降低20%、后坐力降低15%，但每秒消耗0.5耐力。", cat="passive", x=1001, y=1339 },
